exec(open('/tmp/analyze_te.py').read().split('models=[]')[0])

def trans(x,fs):
 s,c,f=x.T;m=c+f
 if fs=='rot':return np.column_stack([1-s-m,s-3*m,f/m])
 if fs=='rat':return np.column_stack([s,s/m,f/m])
 if fs=='eng':return feat(x)
 if fs=='rotfe':return np.column_stack([1-s-m,s-3*m,f])

rows=[]; preds={};oofs={}
for fs in ['rot','rat','eng','rotfe']:
 for nu in [.5,1.5,2.5,np.inf]:
  a,b=trans(X,fs),trans(P,fs)
  kernel=ConstantKernel(1,(.01,10))*Matern(np.ones(a.shape[1]),length_scale_bounds=(.001,100),nu=nu)+WhiteKernel(.4,(.001,3))
  model=make_pipeline(StandardScaler(),GaussianProcessRegressor(kernel=kernel,normalize_y=True,n_restarts_optimizer=3,random_state=42))
  name=f'GP_{fs}_{nu}';t=time.time();oof=np.zeros((len(y),2))
  for j,(itr,iva) in enumerate(splits):
   fit=clone(model).fit(a[itr],y[itr]);oof[iva,j//5]=fit.predict(a[iva])
  rmse=np.sqrt(np.mean((oof-y[:,None])**2));mae=np.mean(np.abs(oof-y[:,None]));high=np.sqrt(np.mean((oof[y>1.]-y[y>1.,None])**2))
  fit=clone(model).fit(a,y);pred=fit.predict(b);preds[name]=pred;oofs[name]=oof
  top=np.argsort(pred)[-12:][::-1]
  print(name,'rmse %.4f mae %.4f hi_rmse %.4f time %.1f'%(rmse,mae,high,time.time()-t),'top',[(po.candidate_id[i],round(pred[i],3)) for i in top],flush=True)
  print('kernel',fit[-1].kernel_,flush=True)
  rows.append([name,rmse,mae,high]);pd.DataFrame(rows,columns=['model','rmse','mae','hi_rmse']).to_csv('/tmp/te_gp_scores.csv',index=False)
  pd.DataFrame(preds,index=po.candidate_id).to_csv('/tmp/te_gp_predictions.csv');np.savez('/tmp/te_gp_oofs.npz',**oofs)

