from scipy.spatial.distance import cdist
from itertools import product
rows=[]; preds={}; oofs={}
for fs in ['raw','rot','rat']:
 def trn(x):
  s,c,f=x.T;m=c+f
  if fs=='raw':return x
  if fs=='rot':return np.column_stack([1-s-m,s-3*m,f/m])
  if fs=='rat':return np.column_stack([s,s/m,f/m])
 a,b=trn(X),trn(P)
 for s1,s2 in product([.1,.3,1,3,10],[.1,.3,1,3,10]):
  scale=np.array([1,s1,s2]);d=cdist(a*scale,a*scale);dp=cdist(b*scale,a*scale)
  for k,weight in product([2,3,5,8,12,20],['uniform','distance']):
   oof=np.zeros((len(y),2))
   def predict(d,yt):
    ind=np.argsort(d,axis=1)[:,:k];dst=np.take_along_axis(d,ind,axis=1)
    w=np.ones_like(dst) if weight=='uniform' else 1/(dst+1e-8)
    return (yt[ind]*w).sum(1)/w.sum(1)
   for j,(itr,iva) in enumerate(splits):oof[iva,j//5]=predict(d[np.ix_(iva,itr)],y[itr])
   rmse=np.sqrt(np.mean((oof-y[:,None])**2));mae=np.mean(np.abs(oof-y[:,None]));high=np.sqrt(np.mean((oof[y>1.]-y[y>1.,None])**2))
   name=f'KNN_{fs}_{s1}_{s2}_{k}_{weight}';rows.append([name,rmse,mae,high]);preds[name]=predict(dp,y);oofs[name]=oof
scores=pd.DataFrame(rows,columns=['model','rmse','mae','hi_rmse']).sort_values('rmse');print(scores.head(25).to_string(index=False))
best=scores.head(10).model.tolist()
for name in best:
 pred=preds[name];top=np.argsort(pred)[-12:][::-1];print(name,[(po.candidate_id[i],round(pred[i],3)) for i in top])
scores.to_csv('/tmp/te_knn_scores.csv',index=False);pd.DataFrame({k:preds[k] for k in best},index=po.candidate_id).to_csv('/tmp/te_knn_predictions.csv');np.savez('/tmp/te_knn_oofs.npz',**{k:oofs[k] for k in best})

